import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawn } from 'node:child_process';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const workerDirectory = join(root, 'workers', 'backend-orchestrator');
const workerWrangler = join(
  root,
  'node_modules',
  '.bin',
  process.platform === 'win32' ? 'wrangler.cmd' : 'wrangler',
);
const outputDirectory = join(root, '.worker-build');
const outputFile = join(outputDirectory, 'index.js');
const generatedFile = join(
  root,
  'src',
  'processing',
  'generated',
  'backend-orchestrator-bundle.ts',
);

await rm(outputDirectory, { recursive: true, force: true });
await new Promise((resolve, reject) => {
  const windows = process.platform === 'win32';
  const child = spawn(
    windows ? process.env.ComSpec || 'cmd.exe' : workerWrangler,
    windows
      ? ['/d', '/c', `call "${workerWrangler}" deploy --dry-run --outdir "${outputDirectory}"`]
      : ['deploy', '--dry-run', '--outdir', outputDirectory],
    { cwd: workerDirectory, stdio: 'inherit', windowsVerbatimArguments: windows },
  );
  child.once('error', reject);
  child.once('exit', code => code === 0
    ? resolve()
    : reject(new Error(`Worker bundle failed with exit code ${code}`)));
});

const source = await readFile(outputFile, 'utf8');
await mkdir(dirname(generatedFile), { recursive: true });
await writeFile(generatedFile, [
  '// Generated by scripts/build-backend-orchestrator-bundle.mjs. Do not edit.',
  `export const BACKEND_ORCHESTRATOR_BUNDLE = ${JSON.stringify(source)};`,
  '',
].join('\n'));
await rm(outputDirectory, { recursive: true, force: true });
